requestAnimationFrame(() => document.body.classList.add('loaded'));

/* Header line + sticky bar after hero */
const header = document.getElementById('header'), bar = document.getElementById('bar');
function onScroll(){
  header.classList.toggle('lined', scrollY > 10);
  bar.classList.toggle('show', scrollY > innerHeight * 0.55);
  drawTrail();
}
addEventListener('scroll', onScroll, {passive:true});

/* Menu drawer */
const drawer = document.getElementById('drawer'), burger = document.getElementById('burger');
function setDrawer(open){ drawer.classList.toggle('open', open); drawer.setAttribute('aria-hidden', !open); burger.setAttribute('aria-expanded', open); document.body.style.overflow = open ? 'hidden' : ''; }
burger.onclick = () => setDrawer(true);
document.getElementById('closer').onclick = () => setDrawer(false);
drawer.querySelectorAll('a').forEach(a => a.addEventListener('click', () => setDrawer(false)));

/* =========================================================
   HERO CANVAS: paint with finger or mouse
   ========================================================= */
const cv = document.getElementById('paint'), ctx = cv.getContext('2d');
let color = '#ED2D7B', strokes = [], drawing = null, autoDone = false;

function sizeCanvas(){
  const r = cv.getBoundingClientRect(), d = Math.min(devicePixelRatio || 1, 2);
  cv.width = r.width * d; cv.height = r.height * d;
  ctx.setTransform(d,0,0,d,0,0);
  redraw();
}
function seg(a, b, c, w, bristles){
  ctx.strokeStyle = c; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.globalAlpha = .92; ctx.lineWidth = w;
  ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
  const dx = b.x - a.x, dy = b.y - a.y, len = Math.hypot(dx, dy) || 1, nx = -dy/len, ny = dx/len;
  ctx.lineWidth = 1.2;
  bristles.forEach(o => {
    ctx.globalAlpha = o.a;
    ctx.beginPath(); ctx.moveTo(a.x + nx*o.d*w, a.y + ny*o.d*w); ctx.lineTo(b.x + nx*o.d*w, b.y + ny*o.d*w); ctx.stroke();
  });
  ctx.globalAlpha = 1;
}
function makeBristles(){ return Array.from({length:7}, () => ({ d:(Math.random()-.5)*1.25, a:.18 + Math.random()*.3 })); }
function redraw(){
  const r = cv.getBoundingClientRect(); ctx.clearRect(0,0,r.width,r.height);
  strokes.forEach(s => {
    const kx = r.width / s.W, ky = r.height / s.H, sc = p => ({ x:p.x*kx, y:p.y*ky });
    for(let i=1;i<s.p.length;i++) seg(sc(s.p[i-1]), sc(s.p[i]), s.c, s.p[i].w, s.b);
  });
}
function pos(e){ const r = cv.getBoundingClientRect(); return { x:e.clientX - r.left, y:e.clientY - r.top, t:performance.now() }; }

cv.addEventListener('pointerdown', e => {
  cv.setPointerCapture(e.pointerId);
  const p = pos(e); p.w = 14;
  const rr = cv.getBoundingClientRect(); drawing = { c:color, b:makeBristles(), p:[p], W:rr.width, H:rr.height }; strokes.push(drawing);
  if(!cv.dataset.touched){ cv.dataset.touched = 1; track('hero_paint'); document.querySelector('.hint').style.opacity = 0; }
});
cv.addEventListener('pointermove', e => {
  if(!drawing) return;
  const p = pos(e), last = drawing.p[drawing.p.length-1];
  const v = Math.hypot(p.x-last.x, p.y-last.y) / Math.max(p.t-last.t, 1);
  p.w = Math.max(5, Math.min(18, 18 - v*6)) * .5 + last.w * .5;
  drawing.p.push(p); seg(last, p, drawing.c, p.w, drawing.b);
});
['pointerup','pointercancel','pointerleave'].forEach(t => cv.addEventListener(t, () => drawing = null));

document.querySelectorAll('.sw').forEach(b => b.onclick = () => {
  color = b.dataset.c;
  document.querySelectorAll('.sw').forEach(x => x.setAttribute('aria-pressed', x === b));
});
document.getElementById('wipe').onclick = () => { strokes = []; redraw(); };

/* The canvas paints a little something by itself on load */
function autoPaint(){
  const r = cv.getBoundingClientRect(), W = r.width, H = r.height;
  const paths = [
    { c:'#ED2D7B', pts: Array.from({length:60}, (_,i) => { const t=i/59; return { x: W*(.08 + .84*t), y: H*(.58 + .12*Math.sin(t*Math.PI*2.2)) }; }) },
    { c:'#000000', pts: Array.from({length:50}, (_,i) => { const a = i/49*Math.PI*2*1.05 - 1.4; return { x: W*.74 + Math.cos(a)*Math.min(W,H)*.14, y: H*.28 + Math.sin(a)*Math.min(W,H)*.14 }; }) },
    { c:'#F7B6CF', pts: Array.from({length:40}, (_,i) => { const t=i/39; return { x: W*(.14 + .4*t), y: H*(.26 + .08*Math.sin(t*Math.PI*3)) }; }) },
    { c:'#ED2D7B', pts: Array.from({length:30}, (_,i) => { const t=i/29; return { x: W*(.2 + .62*t), y: H*(.84 - .04*Math.sin(t*Math.PI)) }; }) }
  ];
  if(reduce){ paths.forEach(pp => strokes.push({ c:pp.c, b:makeBristles(), p:pp.pts.map(p => ({...p, w:12})), W, H })); redraw(); return; }
  let k = 0;
  (function next(){
    if(k >= paths.length){ autoDone = true; return; }
    const pp = paths[k++], s = { c:pp.c, b:makeBristles(), p:[], W, H }; strokes.push(s);
    let i = 0;
    (function step(){
      for(let n=0;n<2 && i<pp.pts.length;n++,i++){
        const p = { ...pp.pts[i], w: 8 + 8*Math.sin(Math.PI * i/pp.pts.length) };
        if(s.p.length) seg(s.p[s.p.length-1], p, s.c, p.w, s.b);
        s.p.push(p);
      }
      if(i < pp.pts.length) requestAnimationFrame(step); else setTimeout(next, 120);
    })();
  })();
}
let rt; addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(sizeCanvas, 150); });
sizeCanvas(); setTimeout(autoPaint, 700);

/* =========================================================
   HOW IT WORKS: the pink line follows your scroll
   ========================================================= */
const steps = document.getElementById('steps'), trail = document.getElementById('trail'), tp = document.getElementById('trailPath');
let trailLen = 0;
function buildTrail(){
  const box = steps.getBoundingClientRect();
  const pts = [...steps.querySelectorAll('.sketch')].map(s => { const r = s.getBoundingClientRect(); return { x: r.left - box.left + r.width/2, y: r.top - box.top + r.height/2 }; });
  trail.setAttribute('viewBox', `0 0 ${box.width} ${box.height}`);
  let d = `M${pts[0].x} ${pts[0].y}`;
  for(let i=1;i<pts.length;i++){
    const a = pts[i-1], b = pts[i], my = (a.y + b.y)/2;
    d += ` C${a.x} ${my + (b.y-a.y)*.2}, ${b.x} ${my - (b.y-a.y)*.2}, ${b.x} ${b.y}`;
    if(Math.abs(b.y - a.y) < 20) d = d.replace(/C[^C]*$/, `C${a.x + (b.x-a.x)*.3} ${a.y - 60}, ${a.x + (b.x-a.x)*.7} ${b.y + 60}, ${b.x} ${b.y}`);
  }
  tp.setAttribute('d', d);
  trailLen = tp.getTotalLength();
  tp.style.setProperty('--len', trailLen);
  drawTrail();
}
function drawTrail(){
  if(!trailLen) return;
  if(reduce){ tp.style.strokeDashoffset = 0; return; }
  const r = steps.getBoundingClientRect();
  const prog = Math.min(1, Math.max(0, (innerHeight*.8 - r.top) / (r.height + innerHeight*.3)));
  tp.style.strokeDashoffset = trailLen * (1 - prog);
}
addEventListener('resize', buildTrail);
addEventListener('load', buildTrail); buildTrail();

/* Gallery frames swing once when they come into view */
const sw = new IntersectionObserver(es => es.forEach(en => { if(en.isIntersecting){ en.target.classList.add('swing'); sw.unobserve(en.target); } }), { threshold:.4 });
document.querySelectorAll('.piece').forEach(p => reduce ? (p.querySelector('.hang').style.transform = `rotate(${getComputedStyle(p).getPropertyValue('--tilt')})`) : sw.observe(p));

/* Occasions: the brush stroke paints under whichever row is in the middle of the screen (mobile) */
const occs = document.querySelectorAll('.occ');
const oo = new IntersectionObserver(es => es.forEach(en => en.target.classList.toggle('on', en.isIntersecting)), { rootMargin:'-49% 0px -49% 0px' });
if(matchMedia('(hover:none)').matches) occs.forEach(o => oo.observe(o));
occs.forEach(o => o.addEventListener('click', () => { const s = document.getElementById('f-occ'); [...s.options].forEach(op => { if(op.text === o.dataset.occ) s.value = op.value; }); }));

/* =========================================================
   REELS
   ========================================================= */
const rail = document.getElementById('reelRail');
const playable = REELS.map((r,i) => ({...r, i})).filter(r => r.src);
const phArt = i => {
  const v = [
    `<rect width="90" height="160" fill="#FFEAF2"/><circle cx="60" cy="40" r="22" fill="#ED2D7B"/><path d="M0 120c30-20 60-20 90 0v40H0z" fill="#000"/>`,
    `<rect width="90" height="160" fill="#000"/><path d="M45 50c18 0 30 18 26 40-4 20-14 30-26 30s-22-10-26-30c-4-22 8-40 26-40z" fill="#ED2D7B"/>`,
    `<rect width="90" height="160" fill="#ED2D7B"/><path d="M10 60c20-20 50 20 70 0M10 90c20-20 50 20 70 0" stroke="#fff" stroke-width="6" fill="none" stroke-linecap="round"/>`
  ];
  return `<svg viewBox="0 0 90 160" preserveAspectRatio="xMidYMid slice">${v[i % 3]}</svg>`;
};
const igId = u => { const m = (u || '').match(/instagram\.com\/(?:reel|reels|p|tv)\/([A-Za-z0-9_-]+)/); return m ? m[1] : null; };
REELS.forEach((r, i) => {
  const id = igId(r.ig);
  if(id){
    const el = document.createElement('div'); el.className = 'reel igreel';
    el.innerHTML = `<span class="tape${i % 2 ? ' b' : ''}"></span><div class="inner"><iframe src="https://www.instagram.com/reel/${id}/embed/" loading="lazy" scrolling="no" allowtransparency="true" allow="encrypted-media; autoplay; clipboard-write" title="${r.caption ? r.caption.replace(/"/g,'') : 'Artizen reel on Instagram'}"></iframe></div>${r.caption ? `<p class="igcap">${r.caption}</p>` : ''}`;
    rail.appendChild(el); return;
  }
  const el = document.createElement('div'); el.className = 'reel';
  el.innerHTML = `<span class="tape"></span><div class="inner">${
    r.src ? `<video muted loop playsinline preload="none" ${r.poster ? `poster="${r.poster}"` : ''}><source src="${r.src}" type="video/mp4"></video>`
          : `<div class="ph-art">${phArt(i)}</div>`
  }<div class="shade"></div><span class="play"><svg><use href="#play"/></svg></span><div class="cap">${r.caption || ''}</div></div>`;
  if(r.src) el.addEventListener('click', () => openReel(playable.findIndex(p => p.i === i)));
  rail.appendChild(el);
});
const ri = new IntersectionObserver(es => es.forEach(en => { const v = en.target.querySelector('video'); if(!v) return; en.isIntersecting ? v.play().catch(()=>{}) : v.pause(); }), { threshold:.6 });
rail.querySelectorAll('.reel').forEach(r => ri.observe(r));

const viewer = document.getElementById('viewer'), vv = document.getElementById('vv'); let cur = 0;
function loadReel(){ const r = playable[cur]; vv.src = r.src; vv.poster = r.poster || ''; vv.muted = false; vv.play().catch(()=>{}); }
function openReel(i){ if(i < 0) return; cur = i; loadReel(); viewer.classList.add('open'); viewer.setAttribute('aria-hidden', false); document.body.style.overflow = 'hidden'; track('reel_open'); }
function closeReel(){ vv.pause(); viewer.classList.remove('open'); viewer.setAttribute('aria-hidden', true); document.body.style.overflow = ''; }
document.getElementById('vx').onclick = closeReel;
document.getElementById('vn').onclick = () => { cur = (cur+1) % playable.length; loadReel(); };
document.getElementById('vp').onclick = () => { cur = (cur-1+playable.length) % playable.length; loadReel(); };
addEventListener('keydown', e => { if(e.key === 'Escape') closeReel(); });
let y0 = null;
viewer.addEventListener('touchstart', e => y0 = e.touches[0].clientY, {passive:true});
viewer.addEventListener('touchend', e => { if(y0 === null || !playable.length) return; const dy = e.changedTouches[0].clientY - y0; if(Math.abs(dy) > 60){ cur = (cur + (dy < 0 ? 1 : -1) + playable.length) % playable.length; loadReel(); } y0 = null; });

