/* Painting carousel: arrows + counter */
(function(){
  const rail = document.getElementById('rail'), prev = document.getElementById('railPrev'), next = document.getElementById('railNext');
  const cnt = document.getElementById('railCount'), fill = document.getElementById('railFill');
  const items = [...rail.querySelectorAll('.piece')];
  const step = () => { const a = items[0], b = items[1]; return b ? b.offsetLeft - a.offsetLeft : rail.clientWidth; };
  const perView = () => Math.max(1, Math.round(rail.clientWidth / step()));
  function update(){
    const max = rail.scrollWidth - rail.clientWidth;
    prev.disabled = rail.scrollLeft < 8; next.disabled = rail.scrollLeft > max - 8;
    const first = Math.min(items.length - 1, Math.round(rail.scrollLeft / step()));
    const pv = perView(), last = Math.min(items.length, first + pv);
    cnt.textContent = pv > 1 ? `${first + 1} to ${last} of ${items.length}` : `${first + 1} of ${items.length}`;
    fill.style.width = (last / items.length * 100) + '%';
  }
  const go = d => { rail.scrollBy({ left: d * step() * (matchMedia('(min-width:920px)').matches ? perView() : 1), behavior: reduce ? 'auto' : 'smooth' }); track('gallery_arrow'); };
  prev.onclick = () => go(-1); next.onclick = () => go(1);
  rail.addEventListener('scroll', () => requestAnimationFrame(update), { passive:true });
  addEventListener('resize', update); update();
  rail.tabIndex = 0;
  rail.addEventListener('keydown', e => { if(e.key === 'ArrowRight'){ e.preventDefault(); go(1); } if(e.key === 'ArrowLeft'){ e.preventDefault(); go(-1); } });
})();

/* Booking form: date from today, exact count for big groups */
(function(){
  const d = new Date(); const today = new Date(d.getTime() - d.getTimezoneOffset()*60000).toISOString().slice(0,10);
  ['f-date','e-date'].forEach(id => document.getElementById(id).min = today);
  const occ = document.getElementById('f-occ'), sel = document.getElementById('f-guests'), cnt = document.getElementById('f-count');
  const BIG = ['Birthday Paint Party','Team Paint Party'];
  occ.addEventListener('change', () => {
    const big = BIG.includes(occ.value);
    sel.hidden = big; cnt.hidden = !big; cnt.required = big;
    document.querySelector('label[for="f-guests"]').textContent = big ? 'Number of guests' : 'Guests';
    if(big) cnt.focus({preventScroll:true});
  });
})();

