  const nameInput = document.getElementById('e-name');

  // Open enquiry popup
  function openEnq(ev) {
    title.textContent = ev;
    eventInput.value = ev;

    // Group size settings
    if (ev === 'Birthday Art Date') {
      sizeInput.min = 2;
      sizeInput.placeholder = 'e.g. 4';
    } else {
      sizeInput.min = 8;
      sizeInput.placeholder = 'e.g. 20';
    }

    // Always display phone number
    phoneWrap.hidden = false;

    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';

    setTimeout(() => nameInput.focus(), 50);
  }

