/* Stickers pop in once when they come into view */
const sio = new IntersectionObserver(es => es.forEach(en => { if(en.isIntersecting){ en.target.classList.add('in'); sio.unobserve(en.target); } }), { threshold:.3 });
document.querySelectorAll('.stk.pop').forEach(s => reduce ? s.classList.add('in') : sio.observe(s));

/* Plan cards: animate only while on screen, plus a gentle pointer tilt */
const planIO = new IntersectionObserver(es => es.forEach(en => { en.target.classList.toggle('live', en.isIntersecting); if(en.isIntersecting) en.target.classList.add('seen'); }), { threshold:.35 });
document.querySelectorAll('.plan').forEach(p => {
  planIO.observe(p);
  if(matchMedia('(hover:hover)').matches && !reduce){
    const ill = p.querySelector('.ill');
    p.addEventListener('pointermove', e => { const r = p.getBoundingClientRect(); ill.style.setProperty('--px', ((e.clientX - r.left)/r.width - .5) * 14 + 'px'); ill.style.setProperty('--py', ((e.clientY - r.top)/r.height - .5) * 14 + 'px'); });
    p.addEventListener('pointerleave', () => { ill.style.setProperty('--px','0px'); ill.style.setProperty('--py','0px'); });
  }
});

