/* Menu */
const catsEl = document.getElementById('cats'), listEl = document.getElementById('menuList'), vegBtn = document.getElementById('vegOnly');
let curCat = 0, vegOnly = false;
const tagCls = t => t === "Chef's special" ? 'cs' : t === 'Must try' ? 'mu' : '';
function renderMenu(){
  const c = MENU[curCat];
  catsEl.querySelectorAll('.cat').forEach((b,i) => b.setAttribute('aria-selected', i === curCat));
  document.getElementById('menuNote').textContent = c.note || '';
  const t = document.getElementById('menuTitle'); t.textContent = c.name; t.classList.remove('swap'); void t.offsetWidth; t.classList.add('swap');
  document.getElementById('menuBand').classList.toggle('drink', c.kind === 'drink');
  ['stkA','stkB'].forEach((id,k) => { const im = document.getElementById(id); im.classList.remove('show'); im.src = STICKERS[c.stk[k]]; void im.offsetWidth; im.classList.add('show'); });
  listEl.innerHTML = c.groups.map(g => {
    const items = g.items.filter(x => !vegOnly || x.v === 'v' || x.v === 'b' || x.v === '');
    if(!items.length) return '';
    return `<div class="mgroup"><h4>${g.t}</h4>${items.map(x => {
      const diet = x.v === 'v' ? '<i class="diet" title="Veg"></i>' : x.v === 'n' ? '<i class="diet n" title="Non veg"></i>' : x.v === 'b' ? (vegOnly ? '<i class="diet" title="Veg"></i>' : '<i class="diet" title="Veg"></i><i class="diet n" title="Non veg"></i>') : '';
      const price = vegOnly && x.v === 'b' ? x.p.split('/')[0] : x.p;
      return `<div class="mi${x.f ? ' fav-row' : ''}"><div class="top"><span class="nm">${x.n}${diet}${x.f ? '<span class="mt cs">Guest favourite</span>' : (x.t ? `<span class="mt ${tagCls(x.t)}">${x.t}</span>` : '')}</span><span class="dots"></span><span class="pr">₹${price}</span></div>${x.d ? `<div class="ds">${x.d}</div>` : ''}</div>`;
    }).join('')}</div>`;
  }).join('') || '<p class="ds">Nothing veg here, try another section.</p>';
}
MENU.forEach((c,i) => { const b = document.createElement('button'); b.className = 'cat'; b.role = 'tab'; b.textContent = c.name; b.onclick = () => { curCat = i; renderMenu(); b.scrollIntoView({block:'nearest', inline:'center', behavior:'smooth'}); track('menu_'+c.id); }; catsEl.appendChild(b); });
vegBtn.onclick = () => { vegOnly = !vegOnly; vegBtn.setAttribute('aria-pressed', vegOnly); renderMenu(); };
renderMenu();
onScroll();


const enquiryForm = document.getElementById('enqForm');

if (enquiryForm) {
  enquiryForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    if (!enquiryForm.reportValidity()) return;

    const formData = new FormData(enquiryForm);

    const name = (formData.get('name') || '').trim();
    const phone = (formData.get('company') || '').trim();
    const date = formData.get('date');
    const guests = formData.get('size');
    const location = formData.get('loc');
    const occasion = formData.get('note');
    const event = formData.get('event');

    const guestCount = /^\d+$/.test(guests)
      ? Number(guests)
      : null;

    const submitButton = enquiryForm.querySelector(
      'button[type="submit"]'
    );

    if (submitButton.disabled) return;

    const originalText = submitButton.textContent;

    submitButton.disabled = true;
    submitButton.textContent = 'Submitting...';

    let status = document.getElementById('enquiryStatus');

    if (!status) {
      status = document.createElement('p');
      status.id = 'enquiryStatus';
      status.setAttribute('role', 'status');
      status.setAttribute('aria-live', 'polite');
      status.style.marginTop = '14px';
      enquiryForm.appendChild(status);
    }

    try {
      if (!window.supabase || !supabaseClient) {
        throw new Error('Supabase is not configured.');
      }

      status.textContent = 'Saving your enquiry...';

      const bookingId = crypto.randomUUID();

      // STEP 1: Save enquiry to existing bookings table
      const { error } = await supabaseClient
        .from('bookings')
        .insert({
          id: bookingId,
          name: name,
          phone: phone,
          visit_date: date,
          guest_selection: guests,
          guest_count: guestCount,
          cafe_location: location,
          occasion: occasion || event
        });

      if (error) throw error;

      console.log('Enquiry saved successfully:', bookingId);

      // STEP 2: Tracking
      try {
        if (typeof track === 'function') {
          track('enquiry_submit');
        }

        if (window.fbq) {
          window.fbq('track', 'Lead');
        }
      } catch (trackingError) {
        console.warn('Tracking error:', trackingError);
      }

      // STEP 3: Email notification (maximum 10 seconds)
      status.textContent = 'Enquiry saved! Processing notification...';

      try {
        const emailRequest =
          supabaseClient.functions.invoke(
            'send-booking-email',
            {
              body: {
                bookingId: bookingId
              }
            }
          );

        const timeout = new Promise(resolve => {
          setTimeout(() => {
            resolve({
              error: new Error('Email notification timed out')
            });
          }, 10000);
        });

        const { error: emailError } = await Promise.race([
          emailRequest,
          timeout
        ]);

        if (emailError) {
          console.error('Email notification issue:', emailError);
        }
      } catch (emailError) {
        console.error('Email notification failed:', emailError);
      }

      // STEP 4: Redirect after successful database insertion
   window.location.href = 'thank-you/';
    } catch (error) {
      console.error('Enquiry submission error:', error);

      status.textContent =
        error.message || "Sorry, we couldn't save your enquiry.";

      submitButton.disabled = false;
      submitButton.textContent = originalText;
    }
  });
}













